function shortestPalindrome(s) {
  const isPal = (end) => {                       // is s[0..end) a palindrome?
    for (let i = 0, j = end - 1; i < j; i++, j--) if (s[i] !== s[j]) return false;
    return true;
  };
  let end = s.length;
  while (!isPal(end)) end--;                     // the longest palindrome prefix
  return [...s.slice(end)].reverse().join("") + s;
}

