boolean isPal(String s, int end) {               // is s[0..end) a palindrome?
    for (int i = 0, j = end - 1; i < j; i++, j--) if (s.charAt(i) != s.charAt(j)) return false;
    return true;
}

bool isPal(const string& s, int end) {           // is s[0..end) a palindrome?
    for (int i = 0, j = end - 1; i < j; i++, j--) if (s[i] != s[j]) return false;
    return true;
}

string shortestPalindrome(string s) {
    int end = s.size();
    while (!isPal(s, end)) end--;                // the longest palindrome prefix
    string rest = s.substr(end);
    reverse(rest.begin(), rest.end());
    return rest + s;
}

function shortestPalindrome(s) {
  const rev = [...s].reverse().join("");
  const t = s + "#" + rev;                     // '#' stops a border from running past s
  const lps = new Array(t.length).fill(0);
  for (let i = 1, len = 0; i < t.length; ) {
    if (t[i] === t[len]) lps[i++] = ++len;
    else if (len > 0) len = lps[len - 1];
    else lps[i++] = 0;
  }
  const keep = lps[t.length - 1];              // the longest prefix of s that is a palindrome
  return rev.slice(0, s.length - keep) + s;    // mirror the rest onto the front
}

def shortest_palindrome(s):
    rev = s[::-1]
    t = s + "#" + rev                     # '#' stops a border from running past s
    lps = [0] * len(t)
    length, i = 0, 1
    while i < len(t):
        if t[i] == t[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            i += 1
    keep = lps[-1]                        # the longest prefix of s that is a palindrome
    return rev[:len(s) - keep] + s        # mirror the rest onto the front

String shortestPalindrome(String s) {
    String rev = new StringBuilder(s).reverse().toString();
    String t = s + "#" + rev;                        // '#' stops a border from running past s
    int[] lps = new int[t.length()];
    for (int i = 1, len = 0; i < t.length(); ) {
        if (t.charAt(i) == t.charAt(len)) lps[i++] = ++len;
        else if (len > 0) len = lps[len - 1];
        else lps[i++] = 0;
    }
    int keep = lps[t.length() - 1];                  // the longest prefix of s that is a palindrome
    return rev.substring(0, s.length() - keep) + s;  // mirror the rest onto the front
}

string shortestPalindrome(string s) {
    string rev(s.rbegin(), s.rend());
    string t = s + "#" + rev;                        // '#' stops a border from running past s
    vector<int> lps(t.size(), 0);
    for (int i = 1, len = 0; i < (int)t.size(); ) {
        if (t[i] == t[len]) lps[i++] = ++len;
        else if (len > 0) len = lps[len - 1];
        else lps[i++] = 0;
    }
    int keep = lps.back();                           // the longest prefix of s that is a palindrome
    return rev.substr(0, s.size() - keep) + s;       // mirror the rest onto the front
}
